from pathlib import Path
import hashlib,json
R=Path('D:/fifaol3/npc-peer-market');server=Path('D:/FO3ID/server')
p=R/'npc_exchange.py';s=p.read_text('utf-8-sig').replace('INITIAL_WALLET=10**17','INITIAL_WALLET=10**15').replace('def __init__(self, market):','def __init__(self, market, model_path=None):').replace("AttributeValueModel(Path(market.h.HERE)/'gamedata/npc_attribute_value.json')","AttributeValueModel(model_path or Path(market.h.HERE)/'gamedata/npc_attribute_value.json')").replace('fee=int(price*FEE_RATE)','fee=price//100')
