s=s.replace("self._worker_status = {'ticks': 0, 'last_tick': None, 'last_error': None, 'errors': 0}","self._worker_status = {'ticks': 0, 'last_tick': None, 'last_error': None, 'errors': 0}\n        self.exchange = NpcExchange(self, getattr(hc, 'NPC_VALUE_MODEL_PATH', None))",1)
