s=s.replace("'ratio': offer['price'] / max(1, self.reference(offer['spid'], offer['grade'])),", "'ratio': offer['price'] / max(1, self.reference(offer['spid'], offer['grade']) * self.exchange.factor(offer['spid'])),\n                 'kind':offer.get('_market_kind','player_sale'),\n                 'buyer':offer.get('_market_buyer'), 'seller':offer.get('_market_seller'),",1)
s=s.replace("rows = self.book(st, sid, stamp)['rows']", "rows = sorted(self.book(st, sid, stamp)['rows'] + self.exchange.listings(st,stamp,sid), key=lambda r:r['price'])",1)
s=s.replace("if r['grade']==grade),None)", "if r['grade']==grade and r['price']==price),None)",1)
s=s.replace("self.h.add_ep(st, -price); player = self.h.add_player(team, spid, grade)", "self.exchange.human_purchase(st,row,stamp)\n            self.h.add_ep(st, -price); player = self.h.add_player(team, spid, grade)",1)
s=s.replace("'background':dict(self._worker_status", "'npc_exchange':self.exchange.status(st,now()),\n                'background':dict(self._worker_status",1)
s=s.replace("'reference_policy':'stable OVR/grade anchor; pack weights never use dynamic quotes'", "'reference_policy':'stable pack/grade anchor; damped attribute model factor .5..2; actual NPC/player trades move quotes'",1)
(R/'market_simulation.py').write_text(s,'utf8')
